import{_ as t,o as n,c as o,a0 as i}from"./chunks/framework.lnbZLl6b.js";const u=JSON.parse('{"title":"Connecting a site","description":"","frontmatter":{},"headers":[],"relativePath":"docs/connecting.md","filePath":"docs/connecting.md"}'),a={name:"docs/connecting.md"};function s(r,e,c,h,l,p){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="connecting-a-site" tabindex="-1">Connecting a site <a class="header-anchor" href="#connecting-a-site" aria-label="Permalink to &quot;Connecting a site&quot;">​</a></h1><p>The first time a website asks Aquilifer for anything, you get an approval popup: plain language, naming the site, asking which of your providers (if you have more than one) to bind to it. You approve or deny it.</p><h2 id="connect-once-then-silent" tabindex="-1">Connect once, then silent <a class="header-anchor" href="#connect-once-then-silent" aria-label="Permalink to &quot;Connect once, then silent&quot;">​</a></h2><p>Once you&#39;ve approved a site, it doesn&#39;t ask again for ordinary use. That&#39;s deliberate, matching how a real extension should feel rather than nagging on every single request. What backs that instead of a popup on every call:</p><ul><li><strong>Rate limits</strong> (see <a href="/projects/aquilifer/docs/rate-limiting">Rate limiting</a>) cap how much any one site can use, automatically, without needing your attention each time.</li><li><strong>History</strong> (see <a href="/projects/aquilifer/docs/history">History</a>) keeps a record of every request a connected site has made, so you can review it later.</li><li><strong>You can disconnect a site at any time</strong>, from the extension&#39;s settings, or with one click from <a href="/projects/aquilifer/docs/popup">the toolbar popup</a> if it&#39;s the site you currently have open, revoking its access immediately.</li></ul><h2 id="switching-providers" tabindex="-1">Switching providers <a class="header-anchor" href="#switching-providers" aria-label="Permalink to &quot;Switching providers&quot;">​</a></h2><p>A site is only ever bound to one provider. If it later needs a different <em>type</em> of provider than the one it&#39;s currently bound to (for example, it wants to talk to Anthropic natively, but you&#39;re currently bound to a self-hosted model), you get a <strong>switch</strong> prompt instead of a plain connect prompt. It&#39;s worded differently (&quot;wants to switch from X to your Anthropic provider&quot;) so it&#39;s clear this replaces the existing binding rather than adding a second one. Denying a switch leaves the site&#39;s current binding untouched; nothing breaks, that one specific call just fails.</p><h2 id="what-if-you-close-the-popup-without-answering" tabindex="-1">What if you close the popup without answering? <a class="header-anchor" href="#what-if-you-close-the-popup-without-answering" aria-label="Permalink to &quot;What if you close the popup without answering?&quot;">​</a></h2><p>Closing it (or clicking Deny) counts as a denial. The site&#39;s request fails with a plain error; nothing is connected, and it can ask again later if you change your mind.</p><h2 id="managing-connected-sites" tabindex="-1">Managing connected sites <a class="header-anchor" href="#managing-connected-sites" aria-label="Permalink to &quot;Managing connected sites&quot;">​</a></h2><p>The <strong>Connected sites</strong> tab in Aquilifer&#39;s settings lists every site you&#39;ve approved and which provider it&#39;s bound to, with a one-click <strong>Disconnect</strong> for each. <a href="/projects/aquilifer/docs/popup">The toolbar popup</a> also shows a Disconnect button for whichever site you currently have open, without needing to go into settings.</p>',11)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
